using UnityEngine;
[DefaultExecutionOrder(550)] public class LocomotiveBrakeSparksV11:MonoBehaviour {
 public LocomotiveController engine;public LocomotiveDriveV9 drive;public LocomotiveDynamicsV10 dynamics;public Material material;
 public ParticleSystem[] sparks;public int emitted;public bool active;float budget;System.Random rng=new System.Random(1123);
 void Start(){sparks=new ParticleSystem[6];int i=0;foreach(float x in new[]{-1.45f,0,1.45f})foreach(float z in new[]{-.775f,.775f}){var g=new GameObject("轮轨急刹火星");g.transform.SetParent(engine.locomotive,false);g.transform.localPosition=new Vector3(x,.015f,z);var ps=g.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.loop=true;m.playOnAwake=false;m.maxParticles=100;m.startLifetime=.25f;m.startSize=.015f;m.startSpeed=0;m.gravityModifier=1.4f;m.simulationSpace=ParticleSystemSimulationSpace.World;var e=ps.emission;e.enabled=false;var sh=ps.shape;sh.enabled=false;var col=ps.colorOverLifetime;col.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(new Color(1,.92f,.51f),0),new GradientColorKey(new Color(1,.28f,.025f),1)},new[]{new GradientAlphaKey(1,0),new GradientAlphaKey(.85f,.45f),new GradientAlphaKey(0,1)});col.color=gradient;var ren=ps.GetComponent<ParticleSystemRenderer>();ren.sharedMaterial=material;ren.renderMode=ParticleSystemRenderMode.Stretch;ren.lengthScale=2;ren.velocityScale=.045f;ren.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;ps.Play();sparks[i++]=ps;}}
 void LateUpdate(){float speed=Mathf.Abs(drive.signedRpm)*Mathf.PI*1.3f/60;active=engine.freeAssembly.Complete&&engine.travel&&!drive.powered&&dynamics.brakeAmount>.60f&&speed>1.35f;if(!active){budget=0;return;}budget+=Time.deltaTime*75;int count=Mathf.FloorToInt(budget);budget-=count;foreach(var ps in sparks)for(int i=0;i<count;i++){float a=(float)rng.NextDouble();var p=new ParticleSystem.EmitParams();p.position=ps.transform.position+new Vector3((a-.5f)*.035f,0,0);p.velocity=new Vector3(-Mathf.Sign(drive.signedRpm)*(.65f+a*1.7f),.35f+(float)rng.NextDouble()*.75f,((float)rng.NextDouble()-.5f)*.8f);p.startSize=.010f+a*.012f;p.startLifetime=.12f+a*.22f;p.startColor=new Color(1,.85f,.3f,1);ps.Emit(p,1);emitted++;}}
}
